package cn.zhuatech.pim.controller; import cn.zhuatech.pim.common.ApiResponse; import cn.zhuatech.pim.dto.PimDto.*; import cn.zhuatech.pim.service.PimService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('CONTENT_STEWARD','ADMIN')") public class StewardController {private final PimService service;public StewardController(PimService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
